import json
import math


def _pearson(x, y):
    n = len(x)
    mean_x = sum(x) / n
    mean_y = sum(y) / n
    cov = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
    std_x = math.sqrt(sum((xi - mean_x) ** 2 for xi in x))
    std_y = math.sqrt(sum((yi - mean_y) ** 2 for yi in y))
    if std_x == 0 or std_y == 0:
        return float('nan')
    return cov / (std_x * std_y)


def numeric_correlation_from_json(json_text):
    # Parse the JSON; raise ValueError if invalid
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("Invalid JSON text")

    if not isinstance(data, dict) or not data:
        raise ValueError("Data must be a non-empty object mapping column names to lists")

    # Validate that all columns are lists of equal, non-zero length
    lengths = set()
    for col, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column '{col}' does not contain a list")
        lengths.add(len(values))
    if 0 in lengths:
        raise ValueError("Data is empty")
    if len(lengths) > 1:
        raise ValueError("All columns must have the same length")

    # Keep only columns whose values are all numeric (int/float, excluding bool)
    numeric_cols = {
        col: [float(v) for v in values]
        for col, values in data.items()
        if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values)
    }

    # Compute pairwise Pearson correlations
    cache = {}
    result = {}
    cols = list(numeric_cols)
    for i, col1 in enumerate(cols):
        result[col1] = {}
        for j, col2 in enumerate(cols):
            key = (i, j) if i <= j else (j, i)
            if key not in cache:
                cache[key] = _pearson(numeric_cols[col1], numeric_cols[col2])
            result[col1][col2] = cache[key]
    return result
```

